import{_ as t,c as a,o as n,ag as o}from"./chunks/framework.Bzez9NG9.js";const r="/space/img/create-jupyter.jpg",s="/space/img/jupyter-sidebar.png",i="/space/img/run-jupyter.png",g=JSON.parse('{"title":"Jupyter","description":"Create and run Jupyter notebooks in SPACE for interactive Python analysis, development, and IBM Planning Analytics workflows.","frontmatter":{"title":"Jupyter","description":"Create and run Jupyter notebooks in SPACE for interactive Python analysis, development, and IBM Planning Analytics workflows.","keywords":["Jupyter","JupyterLab","Python notebooks",".ipynb","kernel","ipykernel","interactive Python","TM1py"],"outline":"deep"},"headers":[],"relativePath":"doc/python/jupyter.md","filePath":"doc/python/jupyter.md"}'),l={name:"doc/python/jupyter.md"};function p(c,e,d,h,u,y){return n(),a("div",null,e[0]||(e[0]=[o('<h1 id="jupyter" tabindex="-1">Jupyter <a class="header-anchor" href="#jupyter" aria-label="Permalink to &quot;Jupyter&quot;">​</a></h1><p>SPACE includes an integrated Jupyter environment for interactive Python development and analysis. Notebooks combine executable Python code with output and explanatory content, making them useful for exploration, prototyping, data analysis, and IBM Planning Analytics workflows.</p><p>For reusable programs and scheduled automation, see <a href="./scripts.html">Python scripts</a>.</p><h2 id="creating-a-notebook" tabindex="-1">Creating a notebook <a class="header-anchor" href="#creating-a-notebook" aria-label="Permalink to &quot;Creating a notebook&quot;">​</a></h2><p>Open the launcher using the <strong>+</strong> icon in the upper-left corner and select a <strong>Python 3</strong> notebook.</p><p><img src="'+r+'" alt="Create Jupyter file" data-zoomable=""></p><p>The new <code>.ipynb</code> file appears in the Python workspace and can be organized alongside scripts and other project files.</p><h2 id="working-with-files" tabindex="-1">Working with files <a class="header-anchor" href="#working-with-files" aria-label="Permalink to &quot;Working with files&quot;">​</a></h2><p>Use the sidebar to navigate the Python workspace and manage files and folders.</p><p>You can create folders to organize projects and use the context menu to rename or delete files.</p><p><img src="'+s+'" alt="Jupyter sidebar" data-zoomable=""></p><p>Python projects can also be maintained in Git. See <a href="./git.html">Git</a> for source-control configuration and workflow.</p><h2 id="running-notebook-code" tabindex="-1">Running notebook code <a class="header-anchor" href="#running-notebook-code" aria-label="Permalink to &quot;Running notebook code&quot;">​</a></h2><p>A notebook is organized into cells that can be executed independently.</p><p>Enter Python code in a cell and run it using the <strong>Run</strong> button or <code>Ctrl+Enter</code>.</p><p><img src="'+i+'" alt="Run Jupyter" data-zoomable=""></p><p>The result appears with the cell, allowing you to inspect values, tables, messages, and errors while developing an analysis incrementally.</p><p>Variables and imported modules remain available in the active kernel while you continue working in the notebook.</p><h2 id="kernels" tabindex="-1">Kernels <a class="header-anchor" href="#kernels" aria-label="Permalink to &quot;Kernels&quot;">​</a></h2><p>A Jupyter kernel is the Python process that executes notebook cells and keeps the notebook&#39;s in-memory state.</p><p>Each active notebook session uses a kernel. Variables, imports, and other Python state created by executed cells remain in that kernel until it is restarted or stopped.</p><p>Restarting a kernel clears its in-memory state, so cells that define required variables or imports need to be executed again.</p><p>The kernel selector in the notebook interface can be used to view or select the available kernel.</p><h2 id="packages-and-space-resources" tabindex="-1">Packages and SPACE resources <a class="header-anchor" href="#packages-and-space-resources" aria-label="Permalink to &quot;Packages and SPACE resources&quot;">​</a></h2><p>Packages installed in the SPACE Python environment can be imported from notebooks. See <a href="./custom-packages.html">Custom packages</a> when an additional Python library is required.</p><p>Notebooks can also use the <a href="./sdk.html">SPACE Python SDK</a> to access supported SPACE-managed resources, including <a href="./secrets-and-connections.html">secrets and connections</a>.</p><p>For IBM Planning Analytics examples using the TM1py library, see <a href="./tm1py.html">TM1py</a>.</p>',27)]))}const k=t(l,[["render",p]]);export{g as __pageData,k as default};
